    return key


def _format(value):
    """去掉无意义的小数零，返回十进制字符串。"""
    s = format(value, "f")
    if "." in s:
        s = s.rstrip("0").rstrip(".")
    if s in ("", "-", "-0"):
        s = "0"
    return s


